import re

def sanitize_tag(tag):
    if 'userid' not in tag:
        return None
    userid = tag.split('userid=')[1].split('>')[0]
    if not re.match(r'^[-a-zA-Z0-9_]+$',userid):
        tag = re.sub(r'tag\s*=\s*([^>]*)', '<tag just got cleaned>',
                      tag, flags=re.IGNORECASE)
        return tag
    else:
        return userid

