import os
import json

def     pack_torrents(torrents_path):
    torrents = []
    for t in os.listdir(torrents_path):
        torrents.append(os.path.join(torrents_path, t))

    tar = tarfile.open('torrents.torrent', 'w:gz')
    for t in torrents:
        tar.add(t)

    tar.close()

def unpack(torrents_path):
    tar = tarfile.open('torrents.torrent', 'r:gz')
    tar.extractall(path='../')

    for t in tar.getmembers():
        if t.name.endswith('.json'):
            json.load(open(t.name))

def unpack_all(torrents_path):
    os.mkdir('data', 0o777)
    unpack(torrents_path)
    for f in os.listdir('data'):
        if f.endswith('asc'):
            os.remove(os.path.join('data', f))

